.toolbar {
  display: flex;          /* flex-direction defaults to row */
  height: 80px;
  justify-content: center;
}

.row { display: flex; width: 400px; }
.icon { width: 40px; }
.text { flex: 1; }

<div class="row">
  <div class="icon"></div>
  <div class="text">https://example.com/a-very-long-unbroken-url-that-keeps-going-and-going</div>
</div>

.grid {
  display: grid;
  width: 600px;
  grid-template-columns: repeat(3, 1fr);
}
/* the first cell contains a 400px-wide image */

.cards {
  display: grid;
  width: 1000px;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
}
/* only 2 cards are rendered */
